func:
// Filtrage de la télémétrie brute d'une station.
// Entrée  : fw/raw/<code>/telemetry (ou floodwatch/stations/<code>/telemetry en mode direct)
// Sortie 1: floodwatch/stations/<code>/telemetry -> file d'attente Cloud
// Sortie 2: mesure filtrée -> règle de sécurité locale
// Diagnostic du capteur (firmware >= 1.2) : echoOk (échos valides de la salve) et echoSpreadCm
// (écart max - min) sont transmis avec la mesure. Une lecture écartée comme aberration n'est
// pas perdue : elle est jointe à la mesure suivante (tableau « outliers »), afin que le Cloud
// garde la trace de TOUTES les lectures et de leur verdict.
const code = msg.topic.split('/')[2];
let data;
try { data = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload; }
catch (e) { node.warn(JSON.stringify({ event: 'invalid_json', station: code })); return null; }

const reg = (global.get('stations') || {})[code] || {};
const cfg = (flow.get('configs') || {})[code] || {};
const SPIKE = Number(env.get('SPIKE_CM'));
const WINDOW = Number(env.get('AVG_WINDOW'));
const sensorHeight = Number(cfg.sensorHeightCm || reg.sensorHeightCm || 30);
const level = Number(data.levelCm);
const now = Date.now();
const topic = `floodwatch/stations/${code}/telemetry`;
const base = {
    rain: Math.min(1, Math.max(0, Number(data.rain || 0))),
    seq: data.seq, ts: now, gw: env.get('GATEWAY_ID'), zone: reg.zone || env.get('GATEWAY_ZONE'),
    gps: reg.lat !== undefined ? { lat: reg.lat, lon: reg.lon } : undefined
};
const round2 = v => Math.round(v * 100) / 100;
const median = a => { const s = [...a].sort((x, y) => x - y); return s[Math.floor(s.length / 2)]; };
const num = v => (v === undefined || v === null || !Number.isFinite(Number(v))) ? undefined : Number(v);
const OUTLIERS_MAX = 5;   // lectures écartées conservées entre deux mesures retenues
const echoOk = num(data.echoOk), echoSpread = num(data.echoSpreadCm);
const diag = {};          // champs absents (ancien firmware) : rien n'est ajouté au message
if (echoOk !== undefined) diag.echoOk = Math.max(0, Math.round(echoOk));
if (echoSpread !== undefined) diag.echoSpreadCm = round2(Math.max(0, echoSpread));
// verdict du classifieur embarqué (firmware >= 1.3) : transmis tel quel, jamais recalculé ici
if (typeof data.suspect === 'boolean') diag.suspect = data.suspect;

// 1. Mesure physiquement impossible ou capteur en défaut : transmise telle quelle (sensorOk=false)
//    pour que le middleware lève l'alerte « capteur défaillant ».
const plausible = Number.isFinite(level) && level >= -2 && level <= sensorHeight + 2 && data.sensorOk !== false;
if (!plausible) {
    node.warn(JSON.stringify({ event: 'sensor_fault', station: code, levelCm: data.levelCm }));
    node.status({ fill: 'red', shape: 'dot', text: `${code} capteur en défaut` });
    return [{ topic, qos: 1, payload: JSON.stringify({ ...base, ...diag, levelCm: Number.isFinite(level) ? level : -1, sensorOk: false }) }, null];
}

// 2. Rejet des aberrations : une valeur à plus de SPIKE cm de la médiane des 3 dernières est un
//    écho parasite (HC-SR04). Deux valeurs proches de suite confirment un vrai changement de niveau.
const all = flow.get('filter') || {};
const s = all[code] || { window: [], pending: null, rejected: 0, outliers: [] };
s.outliers = s.outliers || [];
if (s.window.length >= 3 && Math.abs(level - median(s.window.slice(-3))) > SPIKE) {
    if (s.pending === null || Math.abs(level - s.pending) > SPIKE) {
        s.pending = level;
        s.rejected += 1;
        s.outliers = s.outliers.concat([{ levelCm: level, ...diag, ts: now }]).slice(-OUTLIERS_MAX);
        all[code] = s; flow.set('filter', all);
        node.log(JSON.stringify({ event: 'outlier_rejected', station: code, levelCm: level, rejected: s.rejected }));
        node.status({ fill: 'yellow', shape: 'ring', text: `${code} aberration rejetée (${level} cm)` });
        return null;
    }
    s.window.push(s.pending); // changement confirmé
    s.outliers.pop();         // ... donc la lecture en attente n'était pas une aberration
}
s.pending = null;

// 3. Moyenne glissante sur les WINDOW dernières valeurs retenues
s.window = s.window.concat([level]).slice(-WINDOW);
const outliers = s.outliers.length ? s.outliers : undefined;
s.outliers = [];
all[code] = s; flow.set('filter', all);
const avg = round2(s.window.reduce((a, b) => a + b, 0) / s.window.length);

node.status({ fill: 'green', shape: 'dot', text: `${code} ${avg} cm (brut ${level})` });
return [
    { topic, qos: 1, payload: JSON.stringify({ ...base, ...diag, levelCm: avg, rawLevelCm: level, sensorOk: true, outliers }) },
    { code, levelCm: avg, rawLevelCm: level, ts: now, rain: base.rain }
];

// Règle de sécurité locale de la passerelle (fonctionne SANS Cloud) :
// niveau filtré > SAFETY_PCT % (85 %) du niveau critique -> barrière CLOSE + feu RED envoyés
// directement à la station sur le broker local. Une seule fois par épisode : le verrou est levé
// quand le niveau repasse sous le seuil orange. La réouverture reste décidée par la station
// (temporisation) ou par le Cloud.
const { code, levelCm } = msg;
const cfg = (flow.get('configs') || {})[code] || {};
const reg = (global.get('stations') || {})[code] || {};
const critical = Number(cfg.criticalCm || reg.criticalCm || 20);
const limit = Number(env.get('SAFETY_PCT'));
const orange = Number(cfg.orangePct || 60);
const pct = 100 * levelCm / critical;
const latch = flow.get('safetyLatch') || {};

if (pct > limit && !latch[code]) {
    latch[code] = Date.now();
    flow.set('safetyLatch', latch);
    const uuid = global.get('randomUUID');
    const cmd = (actuator, value) => ({
        topic: `floodwatch/stations/${code}/cmd`, qos: 1, retain: false,
        payload: JSON.stringify({ id: uuid(), actuator, value, ts: Date.now(), origin: 'gateway' })
    });
    const info = { event: 'local_safety', station: code, levelCm, levelPct: Math.round(pct * 10) / 10, limitPct: limit };
    node.warn(JSON.stringify(info));
    node.status({ fill: 'red', shape: 'dot', text: `${code} FERMETURE ${info.levelPct} %` });
    const event = { topic: `floodwatch/gateways/${env.get('GATEWAY_ID')}/events`, qos: 1,
                    payload: JSON.stringify({ type: 'local_safety', station: code, levelPct: info.levelPct, ts: Date.now() }) };
    return [[cmd('barrier', 'CLOSE'), cmd('light', 'RED')], event];
}
if (latch[code] && pct < orange) {
    delete latch[code];
    flow.set('safetyLatch', latch);
    node.status({ fill: 'green', shape: 'ring', text: `${code} sous le seuil orange` });
}
return null;

// Relais montant (broker local -> Cloud) : heartbeat, state, status (LWT), ack, td.
// Le drapeau « retenu » est conservé (state, status et td sont retenus sur le Cloud).
msg.qos = 1;
msg.retain = msg.retain === true;
return msg;

// Dernier contact de chaque station (tout message montant, sauf le LWT « offline »).
const code = msg.topic.split('/')[2];
if (msg.topic.endsWith('/status') && String(msg.payload).includes('offline')) return null;
const seen = flow.get('lastSeen') || {};
seen[code] = Date.now();
flow.set('lastSeen', seen);
return null;

// File d'attente Cloud (store-and-forward).
// - Entrée « status » (nœud Statut du client MQTT Cloud) : suit la connexion ; à la reconnexion,
//   renvoie les messages en attente dans l'ordre.
// - Entrée « message » : transmis si le Cloud est joignable, sinon mis en file (contexte « file » :
//   la file survit au redémarrage de Node-RED). Messages retenus (state, status, td) : seul le
//   dernier par topic est conservé. Au-delà de QUEUE_MAX, les plus anciens sont abandonnés.
const MAX = Number(env.get('QUEUE_MAX'));
if (msg.status) {
    const up = msg.status.fill === 'green';
    const was = flow.get('cloudUp') === true;
    flow.set('cloudUp', up);
    if (up && !was) {
        const queue = flow.get('cloudQueue', 'file') || [];
        flow.set('cloudQueue', [], 'file');
        if (queue.length) {
            node.log(JSON.stringify({ event: 'queue_flush', count: queue.length }));
            for (const m of queue) node.send({ topic: m.topic, payload: m.payload, qos: m.qos, retain: m.retain });
        }
    } else if (!up && was) {
        node.warn(JSON.stringify({ event: 'cloud_down', detail: msg.status.text }));
    }
    node.status(up ? { fill: 'green', shape: 'dot', text: 'Cloud connecté' }
                   : { fill: 'yellow', shape: 'ring', text: `Cloud coupé : ${(flow.get('cloudQueue', 'file') || []).length} en attente` });
    return null;
}
if (flow.get('cloudUp') === true) {
    msg.qos = msg.qos === undefined ? 1 : msg.qos;
    msg.retain = !!msg.retain;
    return msg;
}
let queue = flow.get('cloudQueue', 'file') || [];
const item = { topic: msg.topic, payload: msg.payload, qos: msg.qos === undefined ? 1 : msg.qos, retain: !!msg.retain };
if (item.retain) queue = queue.filter(m => m.topic !== item.topic);
queue.push(item);
if (queue.length > MAX) {
    const dropped = queue.length - MAX;
    queue = queue.slice(dropped);
    node.warn(JSON.stringify({ event: 'queue_overflow', dropped }));
}
flow.set('cloudQueue', queue, 'file');
node.status({ fill: 'yellow', shape: 'ring', text: `Cloud coupé : ${queue.length} en attente` });
return null;

// Relais descendant (Cloud -> broker local) : commandes et configuration (retenue).
msg.qos = 1;
msg.retain = msg.topic.endsWith('/config') ? true : msg.retain === true;
node.log(JSON.stringify({ event: 'downlink', topic: msg.topic }));
return msg;

// Mémorise la configuration retenue (seuils) de chaque station : validation et règle locale.
const code = msg.topic.split('/')[2];
try {
    const configs = flow.get('configs') || {};
    configs[code] = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
    flow.set('configs', configs);
    node.status({ fill: 'blue', shape: 'ring', text: `config ${code}` });
} catch (e) { node.warn(JSON.stringify({ event: 'invalid_config', station: code, detail: e.message })); }
return null;

// Suit la connexion au broker local (pour GET /health).
flow.set('localUp', msg.status.fill === 'green');
return null;

// Chien de garde : station muette depuis plus de MUTE_AFTER_SEC (60 s) -> station_mute ;
// retour de la station -> station_back. Événements envoyés au Cloud via la file d'attente.
const LIMIT = Number(env.get('MUTE_AFTER_SEC')) * 1000;
const seen = flow.get('lastSeen') || {};
const muted = flow.get('muted') || {};
const gw = env.get('GATEWAY_ID');
const now = Date.now();
const out = [];
for (const [code, t] of Object.entries(seen)) {
    const silent = now - t > LIMIT;
    if (silent && !muted[code]) {
        muted[code] = true;
        const ev = { type: 'station_mute', station: code, silentSec: Math.round((now - t) / 1000), ts: now };
        node.warn(JSON.stringify({ event: 'station_mute', ...ev }));
        out.push({ topic: `floodwatch/gateways/${gw}/events`, qos: 1, payload: JSON.stringify(ev) });
    } else if (!silent && muted[code]) {
        delete muted[code];
        out.push({ topic: `floodwatch/gateways/${gw}/events`, qos: 1,
                   payload: JSON.stringify({ type: 'station_back', station: code, ts: now }) });
    }
}
flow.set('muted', muted);
node.status({ fill: Object.keys(muted).length ? 'red' : 'green', shape: 'dot',
              text: `${Object.keys(seen).length} station(s), ${Object.keys(muted).length} muette(s)` });
return [out];

// Message de vie de la passerelle (toutes les 5 min).
const gw = env.get('GATEWAY_ID');
const start = context.get('start') || Date.now();
context.set('start', start);
return { topic: `floodwatch/gateways/${gw}/events`, qos: 1,
         payload: JSON.stringify({ type: 'gateway_alive', uptimeSec: Math.round((Date.now() - start) / 1000),
                                   queued: (flow.get('cloudQueue', 'file') || []).length, ts: Date.now() }) };

// GET /health : 200 si le broker local est joignable (UP, ou DEGRADED si le Cloud est coupé :
// la passerelle continue alors à protéger les stations), 503 sinon.
const localUp = flow.get('localUp') === true;
const cloudUp = flow.get('cloudUp') === true;
const seen = flow.get('lastSeen') || {};
const now = Date.now();
msg.statusCode = localUp ? 200 : 503;
msg.headers = { 'Content-Type': 'application/json; charset=utf-8' };
msg.payload = {
    status: !localUp ? 'DOWN' : (cloudUp ? 'UP' : 'DEGRADED'),
    gateway: env.get('GATEWAY_ID'), localBroker: localUp, cloudBroker: cloudUp,
    queued: (flow.get('cloudQueue', 'file') || []).length,
    stations: Object.fromEntries(Object.entries(seen).map(([c, t]) => [c, { lastSeenAgoSec: Math.round((now - t) / 1000),
                                                                             muted: !!(flow.get('muted') || {})[c] }]))
};
return msg;

// FOG – propagation amont -> aval (fonctionne SANS Cloud).
// La passerelle est le seul nœud qui voit toutes les stations d'une zone ET survit à une coupure
// Internet. Quand une station amont est haute et monte, l'eau atteindra ses stations aval après le
// temps de parcours déclaré dans stations.json (« downstream » : travelSec) :
//   sortie 1 : événement propagation_alert vers le Cloud (file d'attente) ;
//   sortie 2 : commande locale « sampling = WATCH » à la station aval (mesure toutes les 5 s).
// Déclenchement en deux temps :
//   1. RÈGLE (amont) : niveau >= PROP_PCT % (50) du critique et montée >= PROP_SLOPE (0,3 cm/min) sur
//      2 min, ou niveau >= orange et non décroissant ;
//   2. MODÈLE (aval, si la calibration du site aval est disponible, R² >= PROP_MODEL_MIN_R2) : le
//      modèle réservoir calibré du site aval est intégré sur le temps de parcours + PROP_HORIZON_MIN
//      (15 min) ; pré-alerte seulement si le pic projeté atteint l'orange aval. Pluie : prévision
//      météo raccordée à la mesure si disponible, sinon pluie actuelle. Amont : niveaux déjà
//      mesurés pendant le parcours, puis projetés par le modèle de l'amont (PROP_CASCADE).
//      (Le niveau d'équilibre, essayé d'abord, supposait un orage sans fin.)
//   PROP_MODE=rule désactive l'étape 2 (comparaison sur le banc d'essai du fog). Une alerte par lien et par épisode ; réarmement quand
// l'amont redescend sous 80 % de PROP_PCT, et retour de la station aval en NORMAL si plus aucun
// lien actif ne la vise. Historique [ts, niveau filtré, pluie, niveau brut] conservé 45 min,
// lu par la calibration (nœud « Fog : calibration des sites »).
const HIST_MS = 45 * 60 * 1000;
const PROP_PCT = Number(env.get('PROP_PCT') || 50);
const PROP_SLOPE = Number(env.get('PROP_SLOPE_CM_MIN') || 0.3);
const MODE = env.get('PROP_MODE') || 'model';
const MODEL_R2 = Number(env.get('PROP_MODEL_MIN_R2') || 0.2);
const { code, levelCm, ts } = msg;
const rain = Number(msg.rain || 0);
const reg = global.get('stations') || {};
const me = reg[code] || {};

const hist = flow.get('levels') || {};
const h = (hist[code] || []).filter(p => p[0] >= ts - HIST_MS);
h.push([ts, levelCm, rain, Number.isFinite(msg.rawLevelCm) ? msg.rawLevelCm : levelCm]);
hist[code] = h;
flow.set('levels', hist);

const links = me.downstream || [];
if (!links.length) return null;
const cfg = (flow.get('configs') || {})[code] || {};
const critical = Number(cfg.criticalCm || me.criticalCm || 20);
const orange = Number(cfg.orangePct || 60);
const pct = 100 * levelCm / critical;

// pente des moindres carrés sur les 2 dernières minutes (cm/min)
const w = h.filter(p => p[0] >= ts - 120000);
let slope = 0;
if (w.length >= 3 && w[w.length - 1][0] - w[0][0] >= 30000) {
    const t0 = w[w.length - 1][0];
    const xs = w.map(p => (p[0] - t0) / 60000), ys = w.map(p => p[1]);
    const n = xs.length, sx = xs.reduce((a, b) => a + b, 0), sy = ys.reduce((a, b) => a + b, 0);
    const sxx = xs.reduce((a, x) => a + x * x, 0), sxy = xs.reduce((a, x, i) => a + x * ys[i], 0);
    const den = n * sxx - sx * sx;
    slope = Math.abs(den) < 1e-12 ? 0 : (n * sxy - sx * sy) / den;
}
const trigger = (pct >= PROP_PCT && slope >= PROP_SLOPE) || (pct >= orange && slope >= 0);
const calib = flow.get('calibration') || {};
const lastOf = c => { const s = hist[c] || []; return s.length ? s[s.length - 1] : null; };
const HORIZON_MIN = Number(env.get('PROP_HORIZON_MIN') || 15);
// Pluie supposée d'un site au décalage offS (s) : prévision météo flow.rainOutlook[site]
// ({start, stepSec, values 0..1}, posée par le nœud météo ou le banc) ; persistance de la pluie
// mesurée sans prévision ou si elle est périmée. PROP_RAIN_BLEND_S (défaut 0) : raccord à la pluie
// mesurée par un poids exp(-t/τ). 0 = prévision seule : sur le banc, un raccord de 15 min annule le
// gain. Admissible ici car la pré-alerte n'est qu'une couche de conseil (la sécurité locale de la
// station et les alertes du Cloud n'en dépendent pas) ; la prévision du Cloud garde son raccord.
const outlooks = flow.get('rainOutlook') || {};
const BLEND_RAW = env.get('PROP_RAIN_BLEND_S');            // 0 : prévision seule (sans raccord)
const BLEND_S = BLEND_RAW === undefined || BLEND_RAW === '' ? 0 : Number(BLEND_RAW);
const fresh = site => {                         // prévision exploitable du site, ou null
    const o = outlooks[site];
    if (!o || !Array.isArray(o.values) || !o.values.length || !(o.stepSec > 0)) return null;
    return ts < o.start + o.values.length * o.stepSec * 1000 ? o : null;
};
const rainAt = (site, rNow, offS) => {
    const o = fresh(site);
    if (!o) return rNow;
    const at = ts + offS * 1000;
    const k = Math.min(o.values.length - 1, Math.max(0, Math.floor((at - o.start) / (o.stepSec * 1000))));
    const w = BLEND_S > 0 ? Math.exp(-offS / BLEND_S) : 0;
    return w * rNow + (1 - w) * Number(o.values[k] || 0);
};
// Cascade : l'apport amont du site aval = niveaux amont DÉJÀ MESURÉS pendant le temps de parcours,
// puis niveau amont PROJETÉ par le modèle calibré de l'amont. PROP_CASCADE = auto (défaut : seulement
// si l'amont a une prévision de pluie ; sans elle, la projection prolonge un orage sans fin et les
// fausses pré-alertes augmentent sur le banc), 1 (toujours) ou 0 (niveau amont actuel constant,
// version 1.0 ; c'est aussi le comportement de auto sans prévision).
const CASCADE_MODE = env.get('PROP_CASCADE') || 'auto';
const cascadeFor = up => CASCADE_MODE === '1' || (CASCADE_MODE === 'auto' && !!fresh(up));
const STEP_S = 10;
const usable = c => !!c && c.b > 0 && c.r2 !== null && c.r2 >= MODEL_R2;
const levelAt = (site, t) => {                  // dernier niveau filtré connu avant t
    const s = hist[site] || [];
    let v = s.length ? s[0][1] : 0;
    for (const p of s) { if (p[0] <= t) v = p[1]; else break; }
    return v;
};
const memo = {};
const project = (site, durS, depth) => {        // niveaux projetés (pas de 10 s), ou null sans modèle
    const key = site + '|' + durS + '|' + depth;
    if (key in memo) return memo[key];
    const c = calib[site], last = lastOf(site);
    if (!usable(c) || !last) return (memo[key] = null);
    const ups = (c.upstream || []).map(u => ({ code: u.code, travel: Number(u.travelSec || 0),
        cascade: cascadeFor(u.code), proj: cascadeFor(u.code) && depth > 0 ? project(u.code, durS, depth - 1) : null }));
    const inflow = t => {
        let sum = 0;
        for (const u of ups) {
            const tau = t - u.travel;
            if (!u.cascade) { const l = lastOf(u.code); sum += l ? l[1] : 0; }
            else if (tau <= 0) sum += levelAt(u.code, ts + tau * 1000);
            else if (u.proj) sum += u.proj[Math.min(u.proj.length - 1, Math.floor(tau / STEP_S))];
            else { const l = lastOf(u.code); sum += l ? l[1] : 0; }
        }
        return sum;
    };
    let L = last[1];
    const out = [L], r0 = last[2];
    for (let t = 0; t < durS; t += STEP_S) {
        L = Math.max(0, L + (c.a * rainAt(site, r0, t) - c.b * L + (c.g || 0) * inflow(t)) * STEP_S / 60);
        out.push(L);
    }
    return (memo[key] = out);
};
const projected = (target, travelSec) => {      // pic projeté du site aval (cm), ou null sans modèle
    if (MODE !== 'model') return null;
    const levels = project(target, travelSec + HORIZON_MIN * 60, 2);
    return levels ? Math.max(...levels) : null;
};
const active = flow.get('propagation') || {};
const gw = env.get('GATEWAY_ID');
const uuid = global.get('randomUUID');
const events = [], cmds = [];
for (const link of links) {
    const key = `${code}>${link.code}`;
    const tReg = reg[link.code] || {}, tCfg = (flow.get('configs') || {})[link.code] || {};
    const tCritical = Number(tCfg.criticalCm || tReg.criticalCm || 20), tOrange = Number(tCfg.orangePct || 60);
    const eq = trigger ? projected(link.code, Number(link.travelSec || 0)) : null;
    const fire = trigger && (eq === null || 100 * eq / tCritical >= tOrange);
    if (fire && !active[key]) {
        active[key] = ts;
        const ev = { type: 'propagation_alert', from: code, to: link.code, etaSec: Number(link.travelSec || 0),
                     upstreamPct: Math.round(pct * 10) / 10, upstreamSlope: Math.round(slope * 100) / 100,
                     basis: eq === null ? 'rule' : 'model',
                     projectedPct: eq === null ? null : Math.round(1000 * eq / tCritical) / 10, ts };
        node.warn(JSON.stringify({ event: 'propagation_alert', ...ev }));
        events.push({ topic: `floodwatch/gateways/${gw}/events`, qos: 1, payload: JSON.stringify(ev) });
        cmds.push({ topic: `floodwatch/stations/${link.code}/cmd`, qos: 1,
                    payload: JSON.stringify({ id: uuid(), actuator: 'sampling', value: 'WATCH', ts, origin: 'gateway' }) });
    } else if (active[key] && pct < 0.8 * PROP_PCT) {
        delete active[key];
        const stillTargeted = Object.keys(active).some(k => k.endsWith(`>${link.code}`));
        if (!stillTargeted) {
            cmds.push({ topic: `floodwatch/stations/${link.code}/cmd`, qos: 1,
                        payload: JSON.stringify({ id: uuid(), actuator: 'sampling', value: 'NORMAL', ts, origin: 'gateway' }) });
        }
        events.push({ topic: `floodwatch/gateways/${gw}/events`, qos: 1,
                      payload: JSON.stringify({ type: 'propagation_end', from: code, to: link.code, ts }) });
    }
}
flow.set('propagation', active);
node.status({ fill: Object.keys(active).length ? 'yellow' : 'green', shape: 'dot',
              text: `${Object.keys(active).length} propagation(s) en cours` });
return [events.length ? events : null, cmds.length ? cmds : null];

// FOG – calibration de la réponse de chaque site (toutes les 5 min, fonctionne SANS Cloud).
// Modèle réservoir de la station, avec ses apports amont (stations.json) :
//   dL/dt = a·pluie − b·L + g·Σ L_amont(t − τ)        (cm/min)
// Moindres carrés CUMULÉS sur tout l'historique, avec oubli lent (demi-vie CALIB_HALF_LIFE_H, 24 h) :
// un seul orage ne suffit pas à séparer la pluie de l'apport amont, plusieurs épisodes le peuvent.
// Chaque passage n'intègre que les mesures nouvelles. Dérivée sur au moins 30 s (le bruit d'une
// différence de 5 s domine sinon), entre niveaux BRUTS (la moyenne glissante retarde le signal),
// régresseurs pris au milieu de l'intervalle. Résultat publié vers le Cloud (« calibration ») avec
// la topologie amont, pour les prévisions par site. Rien n'est publié avant CALIB_MIN_SAMPLES
// équations ni si la pluie n'a jamais varié (a et b ne seraient pas identifiables).
const MIN = Number(env.get('CALIB_MIN_SAMPLES') || 60);
const HALF_LIFE_MS = Number(env.get('CALIB_HALF_LIFE_H') || 24) * 3600 * 1000;
const SPAN_MS = 30000;
const reg = global.get('stations') || {};
const hist = flow.get('levels') || {};
const gw = env.get('GATEWAY_ID');
const now = Date.now();
const ups = {};
for (const s of Object.values(reg)) {
    for (const d of (s.downstream || [])) (ups[d.code] = ups[d.code] || []).push([s.code, Number(d.travelSec || 0) * 1000]);
}
const levelAt = (series, t) => {               // dernier niveau brut connu avant t
    let v = null;
    for (const p of series) { if (p[0] <= t) v = p[3] !== undefined ? p[3] : p[1]; else break; }
    return v;
};
const solve = (A, y) => {                       // élimination de Gauss avec pivot partiel
    const n = A.length, M = A.map((r, i) => r.concat([y[i]]));
    for (let c = 0; c < n; c++) {
        let p = c;
        for (let r = c + 1; r < n; r++) if (Math.abs(M[r][c]) > Math.abs(M[p][c])) p = r;
        if (Math.abs(M[p][c]) < 1e-12) return null;
        [M[c], M[p]] = [M[p], M[c]];
        for (let r = 0; r < n; r++) if (r !== c) {
            const f = M[r][c] / M[c][c];
            for (let k = c; k <= n; k++) M[r][k] -= f * M[c][k];
        }
    }
    return M.map((r, i) => r[n] / r[i]);
};
const sums = flow.get('calibSums') || {};
const results = flow.get('calibration') || {};
const out = [];
for (const [code, h] of Object.entries(hist)) {
    const upstream = ups[code] || [];
    const k = upstream.length ? 3 : 2;
    let S = sums[code];
    if (!S || S.k !== k) S = { k, A: Array.from({ length: k }, () => new Array(k).fill(0)), xy: new Array(k).fill(0),
                                 y: 0, yy: 0, n: 0, rain: 0, rain2: 0, last: 0, at: now };
    const decay = Math.pow(0.5, (now - S.at) / HALF_LIFE_MS);
    for (let i = 0; i < k; i++) { S.xy[i] *= decay; for (let j = 0; j < k; j++) S.A[i][j] *= decay; }
    S.y *= decay; S.yy *= decay; S.n *= decay; S.rain *= decay; S.rain2 *= decay;
    S.at = now;
    let j = 0, lastUsed = S.last;
    for (let i = 0; i < h.length; i++) {
        if (h[i][0] <= S.last) continue;           // mesure déjà intégrée
        if (j <= i) j = i + 1;
        while (j < h.length && h[j][0] - h[i][0] < SPAN_MS) j++;
        if (j >= h.length) break;                  // intervalle incomplet : au prochain passage
        const dt = h[j][0] - h[i][0];
        if (dt > 3 * SPAN_MS) { lastUsed = h[i][0]; continue; }   // trou de mesures
        const raw = p => (p[3] !== undefined ? p[3] : p[1]);
        const mid = h[i][0] + dt / 2;
        const row = [(h[i][2] + h[j][2]) / 2, -(raw(h[i]) + raw(h[j])) / 2];
        if (k === 3) {
            let sum = 0, ok = true;
            for (const [up, travel] of upstream) {
                const v = levelAt(hist[up] || [], mid - travel);
                if (v === null) { ok = false; break; }
                sum += v;
            }
            if (!ok) { lastUsed = h[i][0]; continue; }
            row.push(sum);
        }
        const y = (raw(h[j]) - raw(h[i])) / (dt / 60000);
        for (let a = 0; a < k; a++) { S.xy[a] += row[a] * y; for (let b = 0; b < k; b++) S.A[a][b] += row[a] * row[b]; }
        S.y += y; S.yy += y * y; S.n += 1; S.rain += row[0]; S.rain2 += row[0] * row[0];
        lastUsed = h[i][0];
    }
    S.last = lastUsed;
    sums[code] = S;
    if (S.n < MIN) continue;
    const rainVar = S.rain2 / S.n - (S.rain / S.n) ** 2;
    if (rainVar < 1e-3) continue;
    const coef = solve(S.A, S.xy);
    if (!coef) continue;
    // R² à partir des sommes : SSres = Σy² − 2·c·Σxy + c·A·c ; SStot = Σy² − (Σy)²/n
    const cXy = coef.reduce((acc, c, a) => acc + c * S.xy[a], 0);
    const cAc = coef.reduce((acc, c, a) => acc + c * S.A[a].reduce((s, v, b) => s + v * coef[b], 0), 0);
    const ssRes = S.yy - 2 * cXy + cAc, ssTot = S.yy - S.y * S.y / S.n;
    const r3 = v => Math.round(v * 1000) / 1000;
    const res = { type: 'calibration', station: code, a: r3(coef[0]), b: r3(coef[1]), g: k === 3 ? r3(coef[2]) : null,
                  n: Math.round(S.n), r2: ssTot > 0 ? r3(1 - ssRes / ssTot) : null,
                  upstream: upstream.map(([c, t]) => ({ code: c, travelSec: t / 1000 })), ts: now };
    results[code] = res;
    out.push({ topic: `floodwatch/gateways/${gw}/events`, qos: 1, payload: JSON.stringify(res) });
}
flow.set('calibSums', sums);
flow.set('calibration', results);
node.status({ fill: 'green', shape: 'dot', text: `${Object.keys(results).length} site(s) calibré(s)` });
return [out.length ? out : null];

// FOG – prévision de pluie pour la propagation (toutes les 15 min). OPTIONNEL :
// WEATHER_PROVIDER=open-meteo l'active (défaut none : persistance de la pluie mesurée). Une requête
// par station (position du registre, arrondie à 0,01°) vers l'API publique d'Open-Meteo, sans clé.
// Sans Internet, rien n'arrive : la prévision existante se périme (3 h) et la passerelle revient
// d'elle-même à la persistance. Seule la position de la station part vers le service.
if ((env.get('WEATHER_PROVIDER') || 'none') !== 'open-meteo') return null;
const base = env.get('WEATHER_URL') || 'https://api.open-meteo.com/v1/forecast';
const reg = global.get('stations') || {};
const out = [];
for (const s of Object.values(reg)) {
    if (!Number.isFinite(s.lat) || !Number.isFinite(s.lon)) continue;
    out.push({ station: s.code, url: `${base}?latitude=${s.lat.toFixed(2)}&longitude=${s.lon.toFixed(2)}`
        + '&minutely_15=precipitation&past_minutely_15=1&forecast_minutely_15=12&timezone=GMT' });
}
return [out];

// FOG – lecture de la prévision Open-Meteo -> flow.rainOutlook[station] = {start, stepSec, values}
// (contrat lu par « Fog : propagation amont -> aval », et rempli de la même façon par le banc
// d'essai). minutely_15.precipitation = mm cumulés sur les 15 min PRÉCÉDANT chaque instant (GMT) :
// les pas sont réalignés sur leur début. Intensité normalisée comme le pluviomètre de la station :
// WEATHER_FULL_MMH (20 mm/h) vaut 1. Réponse inexploitable : ignorée (l'ancienne prévision reste
// valable jusqu'à sa fin de couverture).
const STEP = 900;
const full = Number(env.get('WEATHER_FULL_MMH') || 20);
const m15 = msg.payload && msg.payload.minutely_15;
if (msg.statusCode !== 200 || !m15 || !Array.isArray(m15.time) || !Array.isArray(m15.precipitation)
    || !m15.time.length || m15.time.length !== m15.precipitation.length) {
    node.warn(`prévision météo inexploitable pour ${msg.station} (HTTP ${msg.statusCode})`);
    return null;
}
const first = Date.parse(m15.time[0] + 'Z');
if (!Number.isFinite(first)) return null;
const values = m15.precipitation.map(mm => {
    const v = Number(mm);
    return v > 0 && full > 0 ? Math.min(1, v * 3600 / STEP / full) : 0;
});
const all = flow.get('rainOutlook') || {};
all[msg.station] = { start: first - STEP * 1000, stepSec: STEP, values, source: 'open-meteo', issuedAt: Date.now() };
flow.set('rainOutlook', all);
node.status({ fill: 'green', shape: 'dot', text: `pluie prévue : ${Object.keys(all).length} station(s)` });
return null;
